from __future__ import annotations

import os
import sys
import subprocess
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple, Union
from urllib.parse import urlparse

from git.compat import force_bytes, safe_decode, safe_decode_string

from git.exc import BadName, CheckoutConflict, CommandError, GitCommandError, InvalidGitRepositoryError
from git.types import PathLike


def cygpath(path: PathLike) -> str:
    """Convert path from cygwin style to Windows style."""
    return os.fspath(path)


def expand_path(path: PathLike) -> str:
    """Expand variables and user directory in path."""
    path_str = os.fspath(path)
    return os.path.expandvars(os.path.expanduser(path_str))


def is_cygwin_git() -> bool:
    """Check if the git binary is running on cygwin."""
    return sys.platform == "cygwin" or "CYGWIN" in os.environ


def patch_env(env: Dict[str, str]) -> Dict[str, str]:
    """Update environment variables."""
    if 'GIT_CONFIG' in env:
        env['GIT_CONFIG'] = os.path.abspath(env['GIT_CONFIG'])
    if 'GIT_CONFIG_GLOBAL' in env:
        env['GIT_CONFIG_GLOBAL'] = os.path.abspath(env['GIT_CONFIG_GLOBAL'])
    if 'GIT_CONFIG_SYSTEM' in env:
        env['GIT_CONFIG_SYSTEM'] = os.path.abspath(env['GIT_CONFIG_SYSTEM'])
    return env


def remove_password_if_present(cmd: str) -> str:
    """Remove passwords from git command."""
    url_pattern = re.compile(r'https?://([^:]+):([^@]+)@')
    return url_pattern.sub(r'\1:***@\2', cmd)


def stream_copy(source: Union[BinaryIO, TextIO], destination: Union[BinaryIO, TextIO]) -> None:
    """Copy data from source to destination efficiently."""
    try:
        while True:
            chunk = source.read(io.DEFAULT_BUFFER_SIZE)
            if not chunk:
                break
            destination.write(chunk)
    finally:
        if hasattr(source, 'close'):
            source.close()
        if hasattr(destination, 'close'):
            destination.close()


def finalize_process(proc: subprocess.Popen, stderr: str = "") -> None:
    """Finalize the process and handle errors."""
    try:
        returncode = proc.wait()
        if returncode != 0:
            raise subprocess.CalledProcessError(returncode, proc.args, output=proc.stdout, stderr=stderr)
    finally:
        if hasattr(proc, 'close'):
            proc.close()

def hex_to_bin(hex_str: str) -> bytes:
    """Convert a hexadecimal string to a binary string."""
    return bytes.fromhex(hex_str)


def add_progress(kwargs: Dict[str, Any], git: Git, progress: Optional[CallableProgress] = None) -> Dict[str, Any]:
    """Add progress information to the git command."""
    if progress:
        kwargs['progress'] = progress
    return kwargs

